/** Tests authored before production. Real C/D owners/body and shared AddPoints; scalar/pool vectors are
 * constructed COMPONENT inputs, never natural Results/Frame/World/act completion. All Java UNRUN. */
class TestCdR13Results {
 @Test void futureFactoryRetainsExactSourceAndRejectsForeignOrNullOwnership()throws Exception{
  var a=TestCdR13ResultsAssets.actual();var h=new Harness(a.getFirst());assertTrue(h.body.ownsAct3FutureAssets(a.getFirst().assets()));assertFalse(h.body.ownsAct3FutureAssets(a.get(1).assets()));assertFalse(h.body.ownsAct3FutureAssets(null));assertThrows(IllegalArgumentException.class,()->CdResults.fromAct3FutureAssets(h.placement,a.get(1).assets(),a.get(1).results(),null,null,null,null,null,null,null,null));assertThrows(IllegalArgumentException.class,()->CdResults.fromAct3FutureAssets(h.placement,a.getFirst().assets(),a.get(1).results(),null,null,null,null,null,null,null,null));assertThrows(NullPointerException.class,()->CdResults.fromAct3FutureAssets(null,a.getFirst().assets(),a.getFirst().results(),null,null,null,null,null,null,null,null));assertFalse(h.body.isCurrentCall(null));
 }
 @Test void actualDelayConsumesOnlyTheHighByteAndOriginalCuePrecedesAdvance()throws Exception{
  for(var a:TestCdR13ResultsAssets.actual())for(int timer:new int[]{0x00AB,0x01AB,0x02AB,0x80AB,0xFFAB}){var h=new Harness(a);h.edit(s->s.moveByte(ROUTINE,0).moveWord(RESULTS_TIMER_WORD,timer));h.v.put(CdResults.ReadField.PLC_HEAD_LONG,1);h.run();assertEquals((((timer>>>8)-1)&255)<<8|(timer&255),h.slot().word(RESULTS_TIMER_WORD));assertEquals((timer>>>8)==1?2:0,h.slot().routine());assertEquals((timer>>>8)==1?List.of("plc:16","read:PLC_HEAD_LONG"):List.of(),h.order);h.expired();}
 }
 @Test void queuedHeadAndStrictWrappedUnsignedEdgeRemainActualConditionalReads()throws Exception{
  var a=TestCdR13ResultsAssets.actual().getFirst();for(int head:new int[]{1,-1,Integer.MIN_VALUE}){var h=new Harness(a);h.v.put(CdResults.ReadField.PLC_HEAD_LONG,head);var old=h.placement.capture();h.run();assertEquals(old.pool().slots(),h.pool().capture().slots());assertEquals(List.of("read:PLC_HEAD_LONG"),h.order);}for(int[] p:new int[][]{{65520,320,0},{65520,321,1},{1000,1336,0},{1000,1337,1}}){var h=new Harness(a);h.v.put(CdResults.ReadField.CAMERA_X_WORD,p[0]);h.v.put(CdResults.ReadField.PLAYER_X_WORD,p[1]);h.run();assertEquals(p[2]==0?2:4,h.slot().routine());}
 }
 @Test void actualRowsUseEveryNativeRootAndActByteWithoutChangingDirtyNonwrites()throws Exception{
  for(var a:TestCdR13ResultsAssets.actual())for(int good:new int[]{0,1,255})for(int zone:new int[]{2,0x502}){var h=new Harness(a);h.v.put(CdResults.ReadField.GOOD_FUTURE_BYTE,good);h.v.put(CdResults.ReadField.ZONE_ACT_WORD,zone);var saved=h.placement.capture().savedFlags();h.run();int offset=(zone==0x502?10:0)+(good==0?0:20);for(int whole:new int[]{40,32,33}){var s=h.pool().state(whole);assertEquals(a.results().mappingAddress()+offset,s.longBits(MAPPINGS));assertEquals(480,s.word(RESULTS_TIMER_WORD));assertEquals(zone==0x502?0x82F2:0x83C4,s.word(TILE));assertEquals(4,s.routine());}assertEquals(4,h.pool().state(33).unsignedByte(MAP_FRAME));assertEquals(204,h.slot().word(RESULTS_SCREEN_Y_WORD));assertEquals(272,h.pool().state(32).word(RESULTS_SCREEN_Y_WORD));assertEquals(0,h.draws);assertArrayEquals(saved.copy(),h.placement.capture().savedFlags().copy());assertEquals(zone==0x502?0:1,Collections.frequency(h.order,"read:PLAYER_X_WORD"));}
 }
 @Test void fullDirtyParentAndChildImagesHaveOnlyTheActualRowStores()throws Exception{
  var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());for(int whole:new int[]{40,32,33})h.pool().write(dirty(h.pool().state(whole)).moveByte(ID,whole==40?0x3A:0).moveByte(ROUTINE,whole==40?2:0));var before=h.placement.capture();var expected=new ArrayList<byte[]>();for(var s:before.pool().slots())expected.add(s.copyBytes());int[][] rows={{40,204,0,288,0},{32,272,512,240,1},{33,204,0,288,4}};for(var row:rows){byte[] b=expected.get(row[0]-32);w(b,0x32,480);b[0]=0x3A;b[0x24]=4;w(b,2,0x83C4);l(b,4,h.a.results().mappingAddress());w(b,0xA,row[1]);w(b,8,row[2]);w(b,0x2A,row[3]);b[0x1A]=(byte)row[4];}h.v.put(CdResults.ReadField.GOOD_FUTURE_BYTE,0);h.run();for(int i=0;i<96;i++)assertArrayEquals(expected.get(i),h.pool().state(i+32).copyBytes());assertEquals(before.status(),h.placement.status());assertArrayEquals(before.savedFlags().copy(),h.placement.capture().savedFlags().copy());
 }
 @Test void usaMovementHasSignedDirectionUnsignedDelayAndNoSnapping()throws Exception{
  for(int[] p:new int[][]{{480,0,16,479,8,0},{473,0,16,472,8,0},{472,0,16,471,8,1},{0,0xFFFF,0,0,7,1}}){var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.edit(s->s.moveByte(ROUTINE,4).moveWord(RESULTS_TIMER_WORD,p[0]).moveWord(X,p[1]).moveWord(RESULTS_DEST_X,p[2]));h.run();assertEquals(p[3],h.slot().word(RESULTS_TIMER_WORD));assertEquals(p[4],h.slot().centreX());assertEquals(p[5],h.draws);}
 }
 @Test void completedBonusesUseOriginalKachingThenSharedPointsAndSingleLifeWrap()throws Exception{
  for(var a:TestCdR13ResultsAssets.actual()){var h=new Harness(a);h.bonus(2,100,100);h.world=new CdPlayerTouchResponse.WorldGlobals(7,255,255,4990,5000,0);h.run();assertEquals(0,h.v.get(CdResults.ReadField.TIME_BONUS_WORD).intValue());assertEquals(0,h.v.get(CdResults.ReadField.RING_BONUS_WORD).intValue());assertEquals(45,h.slot().word(RESULTS_TIMER_WORD));assertEquals(5010,h.world.score());assertEquals(0,h.world.lives());assertEquals(0,h.world.updateHudLives());assertTrue(h.order.indexOf("sound:DRIVER_KACHING")<h.order.indexOf("points:20"));assertTrue(h.order.indexOf("points:20")<h.order.indexOf("draw"));assertEquals(1,h.oneUps);assertEquals(1,h.draws);}
 }
 @Test void nonfinalTallyTestsTheTimerHighByteAndBonusSubtractWrapsExactly()throws Exception{
  for(int[] p:new int[][]{{0x100,200,0,0xFF,1},{0x101,200,0,0x100,0},{0,1,0,0,1}}){var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.bonus(p[0],p[1],p[2]);h.run();assertEquals((p[1]-100)&65535,h.v.get(CdResults.ReadField.TIME_BONUS_WORD).intValue());assertEquals(p[3],h.slot().word(RESULTS_TIMER_WORD));assertEquals(p[4],Collections.frequency(h.order,"sound:FM_TALLY"));assertEquals(10,h.world.score());}
 }
 @Test void exhaustedBonusCountdownAdvancesOnlyOnSignedUnderflowAndWarpAtThirty()throws Exception{
  for(int[] p:new int[][]{{31,1,30,6,1},{31,0,30,6,0},{0,1,65535,8,0},{0x8000,1,0x7FFF,6,0}}){var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.bonus(p[0],0,0);h.v.put(CdResults.ReadField.SPECIAL_STAGE_BYTE,p[1]);h.run();assertEquals(p[2],h.slot().word(RESULTS_TIMER_WORD));assertEquals(p[3],h.slot().routine());assertEquals(p[4],Collections.frequency(h.order,"sound:FM_SSWARP"));assertEquals(0,h.points);assertEquals(1,h.draws);assertEquals(p[2]==30?1:0,Collections.frequency(h.order,"read:SPECIAL_STAGE_BYTE"));}
 }
 @Test void actThreeWritesPresentAndNextZoneBeforeFreshPostDrawActZeroTail()throws Exception{
  for(var a:TestCdR13ResultsAssets.actual())for(int attack:new int[]{0,1,255})for(int good:new int[]{0,1,255}){var h=new Harness(a);h.edit(s->s.moveByte(ROUTINE,8));h.v.put(CdResults.ReadField.TIME_ATTACK_MODE_BYTE,attack);h.v.put(CdResults.ReadField.GOOD_FUTURE_BYTE,good);h.v.put(CdResults.ReadField.TIME_STONES_BYTE,0x7F);h.flags=0xA3;h.run();assertEquals(0x100,h.v.get(CdResults.ReadField.ZONE_ACT_WORD).intValue());assertEquals(0,h.v.get(CdResults.ReadField.ACT_BYTE).intValue());assertEquals(1,h.period);assertEquals(attack==0?0xA1:0xA0,h.flags);assertEquals(good,h.v.get(CdResults.ReadField.GOOD_FUTURE_BYTE).intValue());assertEquals(List.of("programme:TIME_ZONE_BYTE:1"),h.order.stream().filter(x->x.startsWith("programme:TIME_ZONE_BYTE")).toList());assertTrue(h.order.indexOf("programme:ZONE_ACT_WORD:256")<h.order.indexOf("action:RESET_SAVED_OBJECT_FLAGS"));assertTrue(h.order.indexOf("action:FADE_OUT_MUSIC")<h.order.indexOf("draw"));assertTrue(h.order.indexOf("draw")<h.order.indexOf("read:ACT_BYTE"));assertEquals("programme:GOOD_FUTURE_FLAGS_CLEAR_BYTE:0",h.order.getLast());assertFalse(h.order.contains("read:TIME_STONES_BYTE"));assertFalse(h.order.contains("read:GOOD_FUTURE_BYTE"));for(byte b:h.placement.capture().savedFlags().slice(2,CdObjectPlacementRuntime.SAVED_BANK_BYTES-2).copy())assertEquals(0,b);}
 }
 @Test void dirtyNativeZoneWordControlsAreNotNormalizedByTheFutureBinding()throws Exception{
  for(int[] p:new int[][]{{0xFF02,0,1},{0x1201,0x1202,2},{0x12FF,0x1200,1}}){var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.edit(s->s.moveByte(ROUTINE,8));h.v.put(CdResults.ReadField.ZONE_ACT_WORD,p[0]);h.v.put(CdResults.ReadField.ACT_BYTE,p[0]&255);h.run();assertEquals(p[1],h.v.get(CdResults.ReadField.ZONE_ACT_WORD).intValue());assertEquals(p[2],h.period);}
 }
 @Test void originalCallbackIdentityExpiresAndClonesNeverBecomeAReceipt()throws Exception{
  var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.before=c->{assertTrue(h.body.isCurrentCall(c));if(c instanceof CdResults.ReadCall x)assertFalse(h.body.isCurrentCall(new CdResults.ReadCall(x.field(),x.actualCut(),x.expectedSource())));assertThrows(IllegalStateException.class,()->h.body.run(40));};h.run();assertFalse(h.calls.isEmpty());h.expired();
 }
 @Test void originalCueAndPointsErrorsKeepTheirNativePrefixAndRetireReceiptEvenForError()throws Exception{
  var a=TestCdR13ResultsAssets.actual().getFirst();var h=new Harness(a);h.edit(s->s.moveByte(ROUTINE,0).moveWord(RESULTS_TIMER_WORD,0x0173));var cue=new AssertionError("original cue");h.before=c->{if(c instanceof CdResults.PlcCall)throw cue;};assertSame(cue,assertThrows(AssertionError.class,h::run));assertEquals(0x0073,h.slot().word(RESULTS_TIMER_WORD));assertEquals(0,h.slot().routine());h.expired();var p=new Harness(a);p.bonus(1,100,100);var points=new IllegalStateException("original points");p.before=c->{if(c instanceof CdResults.PointsCall)throw points;};assertSame(points,assertThrows(IllegalStateException.class,p::run));assertEquals(45,p.slot().word(RESULTS_TIMER_WORD));assertTrue(p.order.contains("sound:DRIVER_KACHING"));assertEquals(0,p.points);p.expired();
 }
 @Test void illegalOtherSlotOrSavedMutationFailsTheFullCutWithoutRollback()throws Exception{
  var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.before=c->{if(c instanceof CdResults.ReadCall)h.pool().write(h.pool().state(127).moveByte(ID,0x77));};assertThrows(IllegalStateException.class,h::run);assertEquals(0x77,h.pool().state(127).id());h.expired();var s=new Harness(h.a);var original=new AssertionError("original plus cut violation");s.before=c->{if(c instanceof CdResults.ReadCall){s.placement.bsetSavedFlag(1,2,CdObjectPlacementRuntime.SavedBit.MEMBER_1);throw original;}};assertSame(original,assertThrows(AssertionError.class,s::run));assertEquals(1,original.getSuppressed().length);s.expired();
 }
 @Test void completedSavedResetPrefixSurvivesTheOriginalActionFault()throws Exception{
  var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());h.edit(s->s.moveByte(ROUTINE,8));var original=new AssertionError("after actual reset");h.after=c->{if(c instanceof CdResults.ProgrammeActionCall x&&x.action()==CdResults.ProgrammeAction.RESET_SAVED_OBJECT_FLAGS)throw original;};assertSame(original,assertThrows(AssertionError.class,h::run));assertEquals(0x100,h.v.get(CdResults.ReadField.ZONE_ACT_WORD).intValue());assertEquals(1,h.placement.capture().savedFlags().unsignedByte(0));assertEquals(1,h.placement.capture().savedFlags().unsignedByte(1));assertFalse(h.order.contains("action:FADE_OUT_MUSIC"));assertEquals(0,original.getSuppressed().length);h.expired();
 }
 @Test void missingOwnersAndInvalidReadWidthsStopAtTheActualNativePrefix()throws Exception{
  var a=TestCdR13ResultsAssets.actual().getFirst();var h=new Harness(a,Set.of(Port.PLC));h.edit(s->s.moveByte(ROUTINE,0).moveWord(RESULTS_TIMER_WORD,0x0155));assertEquals(CdResults.UnsupportedBoundary.PLC_OWNER,assertThrows(CdResults.UnsupportedResults.class,h::run).boundary());assertEquals(0x55,h.slot().word(RESULTS_TIMER_WORD));var x=new Harness(a);x.v.put(CdResults.ReadField.GOOD_FUTURE_BYTE,256);assertEquals(CdResults.UnsupportedBoundary.READ_VALUE_WIDTH,assertThrows(CdResults.UnsupportedResults.class,x::run).boundary());assertEquals(4,x.slot().routine());assertEquals(a.results().mappingAddress(),x.slot().longBits(MAPPINGS));x.expired();
 }
 @Test void allocationExhaustionRetainsParentRowAndNeverInventsAChildOrDraw()throws Exception{
  var h=new Harness(TestCdR13ResultsAssets.actual().getFirst());for(int i=32;i<128;i++)if(i!=40)h.pool().write(h.pool().state(i).moveByte(ID,0x77));var error=assertThrows(CdResults.UnsupportedResults.class,h::run);assertEquals(CdResults.UnsupportedBoundary.ALLOCATION_ADDRESS,error.boundary());assertEquals(4,h.slot().routine());assertEquals(480,h.slot().word(RESULTS_TIMER_WORD));assertEquals(0,h.draws);assertEquals(128,error.value());h.expired();
 }
 @Test void legacyConstructedAssetsKeepTheirExistingNoSourceDelayContract()throws Exception{
  var a=TestCdR13ResultsAssets.actual().getFirst();var p=CdObjectPlacementRuntime.fromAct3FutureAssets(a.assets(),CdAssetBytes.copyOf(new byte[CdObjectPlacementRuntime.SAVED_BANK_BYTES]));p.pool().write(p.pool().state(40).moveByte(ID,0x3A).moveWord(RESULTS_TIMER_WORD,0x0255));var b=new CdResults(p,new CdResults.Assets(CdAssetBytes.copyOf(new byte[0]),CdAssetBytes.copyOf(new byte[0]),0),null,null,null,null,null,null,null,null);assertFalse(b.ownsAct3FutureAssets(a.assets()));assertEquals(0x0155,b.run(40).state().word(RESULTS_TIMER_WORD));assertFalse(b.isCurrentCall(new Object()));
 }
 private enum Port{READ,BONUS,POINTS,PLC,SOUND,DRAW,PROGRAMME,ACTION}
 private static final class Harness {
  final TestCdR13ResultsAssets.Source a;final CdObjectPlacementRuntime placement;final CdResults body;final Map<CdResults.ReadField,Integer> v=new EnumMap<>(CdResults.ReadField.class);final List<String> order=new ArrayList<>();final List<Object> calls=new ArrayList<>();Consumer<Object> before=c->{},after=c->{};int draws,points,oneUps,flags=3,period=2;CdPlayerTouchResponse.WorldGlobals world=new CdPlayerTouchResponse.WorldGlobals(7,3,0,0,5000,0);
  Harness(TestCdR13ResultsAssets.Source a){this(a,Set.of());}
  Harness(TestCdR13ResultsAssets.Source a,Set<Port> absent){this.a=a;placement=CdObjectPlacementRuntime.fromAct3FutureAssets(a.assets(),CdAssetBytes.copyOf(new byte[CdObjectPlacementRuntime.SAVED_BANK_BYTES]));for(var f:CdResults.ReadField.values())v.put(f,0);v.put(CdResults.ReadField.ZONE_ACT_WORD,2);v.put(CdResults.ReadField.ACT_BYTE,2);v.put(CdResults.ReadField.CAMERA_X_WORD,1000);v.put(CdResults.ReadField.PLAYER_X_WORD,1337);edit(s->s.moveByte(ID,0x3A).moveByte(ROUTINE,2).moveByte(SPRITE_FLAGS,128).moveWord(X,100).moveWord(RESULTS_DEST_X,100).moveLong(MAPPINGS,a.results().mappingAddress()));
   body=CdResults.fromAct3FutureAssets(placement,a.assets(),a.results(),absent.contains(Port.READ)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("read:"+c.field());int out=v.get(c.field());after.accept(c);return out;},absent.contains(Port.BONUS)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("bonus:"+c.field()+":"+c.value());switch(c.field()){case TIME_BONUS_WORD->v.put(CdResults.ReadField.TIME_BONUS_WORD,c.value());case RING_BONUS_WORD->v.put(CdResults.ReadField.RING_BONUS_WORD,c.value());default->{}}after.accept(c);},absent.contains(Port.POINTS)?null:c->{enter(c,c.actualCut(),c.expectedSource());points++;order.add("points:"+c.points());var result=CdPlayerTouchResponse.addPoints(world,c.points());world=result.world();if(result.command().isPresent())oneUps++;after.accept(c);},absent.contains(Port.PLC)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("plc:"+c.nativeId());after.accept(c);},absent.contains(Port.SOUND)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("sound:"+c.sound());after.accept(c);},absent.contains(Port.DRAW)?null:c->{enter(c,c.actualCut(),c.expectedSource());draws++;order.add("draw");edit(s->s.moveByte(SPRITE_FLAGS,s.spriteFlags()&127));after.accept(c);},absent.contains(Port.PROGRAMME)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("programme:"+c.field()+":"+c.value());switch(c.field()){case ZONE_ACT_WORD->{v.put(CdResults.ReadField.ZONE_ACT_WORD,c.value());v.put(CdResults.ReadField.ACT_BYTE,c.value()&255);}case GOOD_FUTURE_BYTE->v.put(CdResults.ReadField.GOOD_FUTURE_BYTE,c.value());case GOOD_FUTURE_FLAGS_CLEAR_BYTE->v.put(CdResults.ReadField.GOOD_FUTURE_FLAGS_BYTE,0);case GOOD_FUTURE_FLAGS_SET_BIT->v.put(CdResults.ReadField.GOOD_FUTURE_FLAGS_BYTE,v.get(CdResults.ReadField.GOOD_FUTURE_FLAGS_BYTE)|(1<<c.value()));case PLC_LOAD_FLAGS_CLEAR_BIT0->flags&=~1;case PLC_LOAD_FLAGS_CLEAR_BIT1->flags&=~2;case TIME_ZONE_BYTE->period=c.value();default->{}}after.accept(c);},absent.contains(Port.ACTION)?null:c->{enter(c,c.actualCut(),c.expectedSource());order.add("action:"+c.action());if(c.action()==CdResults.ProgrammeAction.RESET_SAVED_OBJECT_FLAGS)placement.resetSavedObjectFlags();after.accept(c);});
  }
  void enter(Object call,CdObjectPlacementRuntime.Snapshot cut,CdObjectState source){assertTrue(body.isCurrentCall(call));assertEquals(slot(),source);placement.validateRestore(cut);assertEquals(cut.status(),placement.status());assertEquals(cut.pool().slots(),pool().capture().slots());assertArrayEquals(cut.savedFlags().copy(),placement.capture().savedFlags().copy());calls.add(call);before.accept(call);}
  void expired(){for(Object c:calls)assertFalse(body.isCurrentCall(c));}CdObjectPool pool(){return placement.pool();}CdObjectState slot(){return pool().state(40);}void edit(UnaryOperator<CdObjectState> f){pool().write(f.apply(slot()));}CdResults.Result run(){return body.run(40);}void bonus(int timer,int time,int ring){edit(s->s.moveByte(ROUTINE,6).moveWord(RESULTS_TIMER_WORD,timer));v.put(CdResults.ReadField.TIME_BONUS_WORD,time);v.put(CdResults.ReadField.RING_BONUS_WORD,ring);}
 }
 private static CdObjectState dirty(CdObjectState s){for(var f:CdObjectState.ByteField.values())s=s.moveByte(f,0x51+7*f.byteOffset());for(var f:CdObjectState.WordField.values())s=s.moveWord(f,0xA157+0x103*f.byteOffset());for(var f:CdObjectState.LongField.values())s=s.moveLong(f,0xA1536729+0x01030507*f.byteOffset());return s;}
 private static void w(byte[] b,int at,int v){b[at]=(byte)(v>>>8);b[at+1]=(byte)v;}private static void l(byte[] b,int at,int v){w(b,at,v>>>16);w(b,at+2,v);}
}
